insert into public.families (id, name, package_manager, sort) values
  ('debian', 'Debian', 'apt', 0),
  ('arch', 'Arch', 'pacman', 1),
  ('redhat', 'Red Hat', 'dnf', 2),
  ('suse', 'SUSE', 'zypper', 3)
insert into public.distros (id, family_id, name, sort) values
  ('debian', 'debian', 'Debian', 0),
  ('ubuntu', 'debian', 'Ubuntu', 1),
  ('mint', 'debian', 'Linux Mint', 2),
  ('archlinux', 'arch', 'Arch Linux', 3),
  ('cachyos', 'arch', 'CachyOS', 4),
  ('manjaro', 'arch', 'Manjaro', 5),
  ('endeavouros', 'arch', 'EndeavourOS', 6),
  ('fedora', 'redhat', 'Fedora', 7),
  ('rocky', 'redhat', 'Rocky Linux', 8),
  ('alma', 'redhat', 'AlmaLinux', 9),
  ('tumbleweed', 'suse', 'openSUSE Tumbleweed', 10),
  ('leap', 'suse', 'openSUSE Leap', 11)
insert into public.questions (id, family_id, distro_id, difficulty, type, topic, prompt, answers, options, template, broken, hint, explanation, cwd) values
  ('c-f-01', null, null, 'easy', 'choice', 'navigation', '¿Qué comando muestra la carpeta en la que estás ahora?', array['pwd']::text[], array['pwd', 'ls', 'cd', 'whoami']::text[], null, null, 'Sus letras vienen de «print working directory».', 'pwd (print working directory) imprime la ruta completa de la carpeta actual.', null),
  ('c-f-02', null, null, 'easy', 'choice', 'navigation', '¿Qué comando lista los archivos de la carpeta actual?', array['ls']::text[], array['ls', 'dir /w', 'list', 'show']::text[], null, null, 'Viene de «list» y tiene solo dos letras.', 'ls lista el contenido de una carpeta. Sin argumentos, muestra la carpeta actual.', null),
  ('c-f-03', null, null, 'easy', 'complete', 'navigation', 'Entra a la carpeta Documentos.', array['cd']::text[], null, '___ Documentos', null, 'Viene de «change directory».', 'cd (change directory) cambia la carpeta actual.', null),
  ('c-f-04', null, null, 'easy', 'complete', 'navigation', 'Estás en ~/Documentos. Sube a la carpeta padre.', array['..']::text[], null, 'cd ___', null, 'Son dos caracteres iguales.', '«..» siempre representa la carpeta padre de la actual.', '~/Documentos'),
  ('c-f-05', null, null, 'easy', 'choice', 'navigation', '¿Qué hace el comando «cd ~»?', array['Te lleva a tu carpeta personal']::text[], array['Te lleva a tu carpeta personal', 'Borra la carpeta actual', 'Muestra los archivos ocultos', 'Cierra la terminal']::text[], null, null, 'La virgulilla ~ es un atajo muy usado.', '~ equivale a tu carpeta personal (/home/tu_usuario). «cd» sin nada hace lo mismo.', null),
  ('c-f-06', null, null, 'easy', 'complete', 'navigation', 'Lista también los archivos ocultos.', array['-a', '-A']::text[], null, 'ls ___', null, 'Es la opción de «all».', 'ls -a muestra todo, incluidos los archivos que empiezan con punto.', null),
  ('c-f-07', null, null, 'easy', 'choice', 'navigation', '¿Qué indica que un archivo empiece con punto, como .bashrc?', array['Es un archivo oculto']::text[], array['Es un archivo oculto', 'Es un archivo borrado', 'Es un virus', 'Es un archivo de Windows']::text[], null, null, 'No aparece con un simple ls.', 'En Linux, los archivos que empiezan con punto son ocultos. Se suelen usar para configuraciones.', null),
  ('c-f-08', null, null, 'easy', 'complete', 'navigation', 'Lista los archivos en formato largo (permisos, tamaño y fecha).', array['-l']::text[], null, 'ls ___', null, 'Es la letra de «long».', 'ls -l muestra una línea por archivo con permisos, dueño, tamaño y fecha.', null),
  ('c-f-09', null, null, 'easy', 'choice', 'navigation', '¿Cuál es la carpeta raíz de todo el sistema Linux?', array['/']::text[], array['/', 'C:\', '~', '/root']::text[], null, null, 'Es un solo carácter.', 'Todo en Linux cuelga de «/». /root es la carpeta personal del administrador, no la raíz.', null),
  ('c-f-10', null, null, 'easy', 'complete', 'navigation', 'Ve directamente a la raíz del sistema.', array['/']::text[], null, 'cd ___', null, 'La raíz es una barra.', 'cd / te lleva a la raíz, de donde cuelgan /home, /etc, /var, etc.', null),
  ('c-f-11', null, null, 'easy', 'choice', 'navigation', '¿Qué tecla autocompleta nombres de archivos y comandos?', array['Tab']::text[], array['Tab', 'Enter', 'Esc', 'Shift']::text[], null, null, 'Está a la izquierda de la Q.', 'Tab completa nombres. Si hay varias opciones, púlsala dos veces para verlas.', null),
  ('c-f-12', null, null, 'easy', 'complete', 'navigation', 'Vuelve a la carpeta en la que estabas justo antes.', array['-']::text[], null, 'cd ___', null, 'Es un solo signo.', '«cd -» alterna entre la carpeta actual y la anterior.', null),
  ('c-f-13', null, null, 'easy', 'choice', 'files', '¿Qué comando crea una carpeta nueva?', array['mkdir']::text[], array['mkdir', 'touch', 'newdir', 'md']::text[], null, null, 'Viene de «make directory».', 'mkdir crea carpetas. touch crea archivos vacíos.', null),
  ('c-f-14', null, null, 'easy', 'complete', 'files', 'Crea la carpeta «fotos».', array['mkdir']::text[], null, '___ fotos', null, 'make + directory.', 'mkdir fotos crea la carpeta fotos en la carpeta actual.', null),
  ('c-f-15', null, null, 'easy', 'complete', 'files', 'Crea un archivo vacío llamado lista.txt.', array['touch']::text[], null, '___ lista.txt', null, 'Significa «tocar» en inglés.', 'touch crea un archivo vacío (o actualiza su fecha si ya existe).', null),
  ('c-f-16', null, null, 'easy', 'choice', 'files', '¿Qué comando muestra el contenido de un archivo de texto?', array['cat']::text[], array['cat', 'ls', 'open', 'type']::text[], null, null, 'Tiene nombre de animal en inglés.', 'cat (concatenate) imprime el contenido de uno o varios archivos.', null),
  ('c-f-17', null, null, 'easy', 'complete', 'files', 'Muestra el contenido de notas.txt.', array['cat']::text[], null, '___ Documentos/notas.txt', null, 'El comando «gato».', 'cat Documentos/notas.txt imprime el archivo en la terminal.', null),
  ('c-f-18', null, null, 'easy', 'choice', 'files', '¿Qué comando copia archivos?', array['cp']::text[], array['cp', 'mv', 'copy', 'dup']::text[], null, null, 'Abreviatura de «copy».', 'cp origen destino copia. Para carpetas se necesita la opción -r.', null),
  ('c-f-19', null, null, 'easy', 'choice', 'files', '¿Qué comando mueve o renombra archivos?', array['mv']::text[], array['mv', 'cp', 'ren', 'rename']::text[], null, null, 'Abreviatura de «move».', 'mv sirve tanto para mover como para renombrar.', null),
  ('c-f-20', null, null, 'easy', 'complete', 'files', 'Renombra notas.txt a apuntes.txt.', array['mv']::text[], null, '___ notas.txt apuntes.txt', null, 'Renombrar es «mover» a otro nombre.', 'mv notas.txt apuntes.txt cambia el nombre del archivo.', '~/Documentos'),
  ('c-f-21', null, null, 'easy', 'choice', 'files', '¿Qué comando borra un archivo?', array['rm']::text[], array['rm', 'del', 'erase', 'delete']::text[], null, null, 'Abreviatura de «remove».', 'rm borra archivos. ¡Cuidado! En la terminal no hay papelera.', null),
  ('c-f-22', null, null, 'easy', 'complete', 'files', 'Borra el archivo tareas.txt.', array['rm']::text[], null, '___ tareas.txt', null, 'remove.', 'rm tareas.txt elimina el archivo de forma permanente.', '~/Documentos'),
  ('c-f-23', null, null, 'easy', 'complete', 'files', 'Copia notas.txt a la carpeta respaldo.', array['respaldo', '~/respaldo', './respaldo']::text[], null, 'cp Documentos/notas.txt ___', null, 'El destino es el nombre de la carpeta.', 'cp origen destino: si el destino es una carpeta, el archivo se copia dentro.', null),
  ('c-f-24', null, null, 'easy', 'choice', 'files', '¿Qué hace «rmdir vacia»?', array['Borra la carpeta «vacia» solo si está vacía']::text[], array['Borra la carpeta «vacia» solo si está vacía', 'Borra la carpeta y todo su contenido', 'Renombra la carpeta', 'Crea la carpeta']::text[], null, null, 'Es la versión prudente de borrar carpetas.', 'rmdir solo borra carpetas vacías. Para borrar con contenido se usa rm -r.', null),
  ('c-f-25', null, null, 'easy', 'choice', 'files', '¿Qué comando limpia la pantalla de la terminal?', array['clear']::text[], array['clear', 'cls', 'clean', 'reset-screen']::text[], null, null, 'En Windows es cls, en Linux es otro.', 'clear limpia la pantalla. También funciona el atajo Ctrl + L.', null),
  ('c-f-26', null, null, 'easy', 'complete', 'files', 'Escribe «Hola» en la pantalla.', array['echo']::text[], null, '___ Hola', null, 'Significa «eco».', 'echo repite en pantalla el texto que le pases.', null),
  ('c-f-27', null, null, 'easy', 'choice', 'files', '¿Qué hace «echo Hola > saludo.txt»?', array['Guarda «Hola» en saludo.txt reemplazando su contenido']::text[], array['Guarda «Hola» en saludo.txt reemplazando su contenido', 'Muestra saludo.txt', 'Borra saludo.txt', 'Añade «Hola» al final sin borrar nada']::text[], null, null, 'Un solo > es peligroso.', '> redirige la salida a un archivo y lo sobrescribe. >> añade al final.', null),
  ('c-f-28', null, null, 'easy', 'choice', 'files', '¿Qué operador AÑADE texto al final de un archivo sin borrar lo anterior?', array['>>']::text[], array['>>', '>', '|', '<']::text[], null, null, 'Es el doble de algo.', '>> agrega al final. > reemplaza todo el contenido.', null),
  ('c-f-29', null, null, 'easy', 'choice', 'files', '¿Qué comando muestra las primeras 10 líneas de un archivo?', array['head']::text[], array['head', 'tail', 'top', 'first']::text[], null, null, 'Significa «cabeza».', 'head muestra el inicio. tail muestra el final.', null),
  ('c-f-30', null, null, 'easy', 'choice', 'files', '¿Qué comando muestra las últimas líneas de un archivo?', array['tail']::text[], array['tail', 'head', 'end', 'last']::text[], null, null, 'Significa «cola».', 'tail muestra el final de un archivo; con -f sigue mostrando lo que se agrega.', null),
  ('c-f-31', null, null, 'easy', 'choice', 'system', '¿Qué comando muestra tu nombre de usuario?', array['whoami']::text[], array['whoami', 'pwd', 'user', 'me']::text[], null, null, 'Pregunta «¿quién soy?» en inglés.', 'whoami («who am I») muestra el usuario con el que trabajas.', null),
  ('c-f-32', null, null, 'easy', 'choice', 'system', '¿Qué comando muestra el manual de otro comando?', array['man']::text[], array['man', 'help', 'doc', 'info-all']::text[], null, null, 'Abreviatura de «manual».', 'man comando abre su manual. Sales con la tecla q.', null),
  ('c-f-33', null, null, 'easy', 'complete', 'system', 'Abre el manual del comando ls.', array['man']::text[], null, '___ ls', null, 'manual.', 'man ls muestra todas las opciones de ls.', null),
  ('c-f-34', null, null, 'easy', 'choice', 'permissions', '¿Para qué sirve sudo?', array['Ejecutar un comando con permisos de administrador']::text[], array['Ejecutar un comando con permisos de administrador', 'Borrar el sistema', 'Cambiar de carpeta', 'Apagar el equipo']::text[], null, null, '«superuser do».', 'sudo ejecuta un comando como administrador (root). Te pide tu contraseña.', null),
  ('c-f-35', null, null, 'easy', 'choice', 'system', '¿Qué comando muestra los comandos que escribiste antes?', array['history']::text[], array['history', 'last', 'log', 'past']::text[], null, null, 'Historia en inglés.', 'history lista tu historial. También puedes navegarlo con las flechas ↑ y ↓.', null),
  ('c-f-36', null, null, 'easy', 'choice', 'permissions', 'En los permisos «-rwxr-xr--», ¿qué significa la x?', array['Permiso de ejecución']::text[], array['Permiso de ejecución', 'Archivo eliminado', 'Archivo oculto', 'Permiso de escritura']::text[], null, null, 'r = leer, w = escribir, x = …', 'r (read) leer, w (write) escribir, x (execute) ejecutar.', null),
  ('c-f-37', null, null, 'easy', 'choice', 'permissions', '¿Qué comando cambia los permisos de un archivo?', array['chmod']::text[], array['chmod', 'chown', 'perm', 'chperm']::text[], null, null, 'change + mode.', 'chmod cambia permisos. chown cambia el dueño.', null),
  ('c-f-38', null, null, 'easy', 'choice', 'permissions', '¿Qué comando cambia el dueño de un archivo?', array['chown']::text[], array['chown', 'chmod', 'owner', 'su']::text[], null, null, 'change + owner.', 'chown usuario archivo cambia el dueño.', null),
  ('c-f-39', null, null, 'easy', 'complete', 'permissions', 'Da permiso de ejecución a script.sh.', array['+x', 'u+x', 'a+x']::text[], null, 'chmod ___ script.sh', null, 'Se «suma» la x.', 'chmod +x agrega el permiso de ejecución.', '~/proyectos'),
  ('c-f-40', null, null, 'easy', 'choice', 'search', '¿Qué comando busca texto dentro de archivos?', array['grep']::text[], array['grep', 'find', 'search', 'look']::text[], null, null, 'Tiene cuatro letras y empieza con g.', 'grep busca líneas que contengan un texto. find busca archivos por nombre.', null),
  ('c-f-41', null, null, 'easy', 'complete', 'search', 'Busca la palabra «linux» en notas.txt.', array['grep']::text[], null, '___ linux Documentos/notas.txt', null, 'Busca TEXTO dentro de archivos.', 'grep texto archivo muestra las líneas que contienen ese texto.', null),
  ('c-f-42', null, null, 'easy', 'choice', 'search', '¿Qué comando busca archivos por su nombre?', array['find']::text[], array['find', 'grep', 'seek', 'locate-all']::text[], null, null, 'Significa «encontrar».', 'find carpeta -name nombre busca archivos y carpetas.', null),
  ('c-f-43', null, null, 'easy', 'choice', 'search', '¿Qué hace el símbolo | (tubería)?', array['Envía la salida de un comando a otro']::text[], array['Envía la salida de un comando a otro', 'Separa carpetas', 'Comenta una línea', 'Borra la salida']::text[], null, null, 'Conecta dos comandos.', 'comando1 | comando2: la salida de comando1 se convierte en la entrada de comando2.', null),
  ('c-f-44', null, null, 'easy', 'complete', 'search', 'Muestra solo las líneas de ls que contienen «txt».', array['grep']::text[], null, 'ls Documentos | ___ txt', null, 'El buscador de texto.', 'La tubería pasa la lista a grep, que filtra las líneas.', null),
  ('c-f-45', null, null, 'easy', 'choice', 'processes', '¿Qué combinación de teclas detiene el comando que se está ejecutando?', array['Ctrl + C']::text[], array['Ctrl + C', 'Ctrl + V', 'Ctrl + S', 'Alt + F4']::text[], null, null, 'La misma que copiar en Windows… pero aquí no copia.', 'Ctrl + C envía la señal de interrupción al programa en primer plano.', null),
  ('c-f-46', null, null, 'easy', 'choice', 'processes', '¿Qué comando muestra los procesos en tiempo real?', array['top']::text[], array['top', 'ps', 'proc', 'tasks']::text[], null, null, 'Lo de arriba, lo mejor.', 'top (o htop) muestra procesos y su uso de CPU y memoria en vivo. ps toma una foto.', null),
  ('c-f-47', null, null, 'easy', 'choice', 'services', '¿Qué es systemd?', array['El sistema que arranca y controla los servicios']::text[], array['El sistema que arranca y controla los servicios', 'Un editor de texto', 'Un gestor de paquetes', 'Un navegador']::text[], null, null, 'Se controla con systemctl.', 'systemd arranca el sistema y gestiona servicios. Lo usan las cuatro familias.', null),
  ('c-f-48', null, null, 'easy', 'choice', 'network', '¿Qué comando comprueba si hay conexión con otro equipo?', array['ping']::text[], array['ping', 'ssh', 'ip', 'net']::text[], null, null, 'Suena como el tenis de mesa.', 'ping envía paquetes y mide si vuelven y cuánto tardan.', null),
  ('c-f-49', null, null, 'easy', 'choice', 'network', '¿Qué comando muestra las direcciones IP del equipo?', array['ip a']::text[], array['ip a', 'ipconfig', 'ping', 'netip']::text[], null, null, 'En Windows es ipconfig, en Linux es más corto.', 'ip a (ip address) lista las interfaces de red y sus direcciones.', null),
  ('c-f-50', null, null, 'easy', 'choice', 'network', '¿Qué comando permite conectarte a otro equipo de forma remota y segura?', array['ssh']::text[], array['ssh', 'ping', 'ls', 'cd']::text[], null, null, 'Secure Shell.', 'ssh usuario@servidor abre una terminal cifrada en otro equipo.', null),
  ('c-m-01', null, null, 'medium', 'write', 'navigation', 'Entra a la carpeta proyectos/web con un solo comando.', array['cd proyectos/web', 'cd ~/proyectos/web', 'cd ./proyectos/web']::text[], null, null, null, 'Puedes encadenar carpetas con /.', 'cd acepta rutas con varias carpetas: cd proyectos/web.', null),
  ('c-m-02', null, null, 'medium', 'write', 'navigation', 'Lista todos los archivos, incluidos los ocultos, en formato largo.', array['ls -la', 'ls -al', 'ls -l -a']::text[], null, null, null, 'Combina dos opciones de ls.', 'ls -la junta -l (formato largo) y -a (todos).', null),
  ('c-m-03', null, null, 'medium', 'write', 'navigation', 'Lista el contenido de la carpeta Descargas sin entrar en ella.', array['ls Descargas', 'ls ~/Descargas', 'ls ./Descargas']::text[], null, null, null, 'ls acepta una ruta.', 'ls carpeta muestra el contenido de esa carpeta sin cambiar de lugar.', null),
  ('c-m-04', null, null, 'medium', 'write', 'files', 'Crea la estructura de carpetas tareas/2026/octubre en un solo comando.', array['mkdir -p tareas/2026/octubre']::text[], null, null, null, 'mkdir necesita una opción para crear las carpetas intermedias.', 'mkdir -p (parents) crea toda la ruta, aunque las carpetas intermedias no existan.', null),
  ('c-m-05', null, null, 'medium', 'write', 'files', 'Copia la carpeta proyectos completa dentro de respaldo.', array['cp -r proyectos respaldo', 'cp -R proyectos respaldo', 'cp -a proyectos respaldo']::text[], null, null, null, 'Para copiar carpetas, cp necesita ser recursivo.', 'cp -r copia la carpeta y todo lo que contiene.', null),
  ('c-m-06', null, null, 'medium', 'write', 'files', 'Borra la carpeta Musica y todo su contenido.', array['rm -r Musica', 'rm -rf Musica', 'rm -R Musica']::text[], null, null, null, 'rm también necesita ser recursivo.', 'rm -r borra carpetas con contenido. ¡Úsalo con cuidado!', null),
  ('c-m-07', null, null, 'medium', 'write', 'files', 'Mueve foto.jpg de Descargas a la carpeta Imagenes.', array['mv Descargas/foto.jpg Imagenes', 'mv ~/Descargas/foto.jpg ~/Imagenes', 'mv Descargas/foto.jpg ~/Imagenes']::text[], null, null, null, 'mv origen destino.', 'mv Descargas/foto.jpg Imagenes mueve el archivo dentro de la carpeta Imagenes.', null),
  ('c-m-08', null, null, 'medium', 'write', 'files', 'Muestra las primeras 5 líneas de /var/log/syslog.', array['head -n 5 /var/log/syslog', 'head -5 /var/log/syslog', 'head -n5 /var/log/syslog']::text[], null, null, null, 'head con la opción -n.', 'head -n 5 limita la salida a 5 líneas.', null),
  ('c-m-09', null, null, 'medium', 'write', 'files', 'Muestra las últimas 20 líneas de /var/log/syslog.', array['tail -n 20 /var/log/syslog', 'tail -20 /var/log/syslog', 'tail -n20 /var/log/syslog']::text[], null, null, null, 'tail con la opción -n.', 'tail -n 20 muestra las 20 líneas finales.', null),
  ('c-m-10', null, null, 'medium', 'write', 'files', 'Cuenta cuántas líneas tiene Documentos/notas.txt.', array['wc -l Documentos/notas.txt', 'wc -l ~/Documentos/notas.txt', 'cat Documentos/notas.txt | wc -l']::text[], null, null, null, 'word count, con la opción de líneas.', 'wc -l cuenta líneas. Sin opciones, wc muestra líneas, palabras y bytes.', null),
  ('c-m-11', null, null, 'medium', 'write', 'files', 'Crea un enlace simbólico llamado «web» que apunte a proyectos/web.', array['ln -s proyectos/web web', 'ln -s ~/proyectos/web web', 'ln -s ~/proyectos/web ~/web']::text[], null, null, null, 'ln con la opción de enlace simbólico. Primero el destino real, luego el nombre del enlace.', 'ln -s destino nombre_enlace crea un acceso directo.', null),
  ('c-m-12', null, null, 'medium', 'write', 'files', 'Guarda el texto «hola mundo» en el archivo saludo.txt usando echo.', array['echo "hola mundo" > saludo.txt', 'echo hola mundo > saludo.txt']::text[], null, null, null, 'echo y el operador de redirección.', '> envía la salida de echo al archivo, creándolo o reemplazándolo.', null),
  ('c-m-13', null, null, 'medium', 'write', 'permissions', 'Da permiso de ejecución a proyectos/script.sh.', array['chmod +x proyectos/script.sh', 'chmod u+x proyectos/script.sh', 'chmod a+x proyectos/script.sh']::text[], null, null, null, 'chmod con +x.', 'chmod +x hace que el archivo se pueda ejecutar con ./script.sh.', null),
  ('c-m-14', null, null, 'medium', 'write', 'permissions', 'Cambia el dueño de informe.txt al usuario ana (necesitas ser administrador).', array['sudo chown ana informe.txt']::text[], null, null, null, 'sudo + chown.', 'Solo root puede regalar archivos a otro usuario, por eso se necesita sudo.', '~/Documentos'),
  ('c-m-15', null, null, 'medium', 'write', 'permissions', 'Cambia los permisos de app.py a 644 (rw-r--r--).', array['chmod 644 app.py']::text[], null, null, null, 'chmod con números: 6 = rw, 4 = r.', 'En notación numérica r=4, w=2, x=1. 644 = dueño lee y escribe, el resto solo lee.', '~/proyectos'),
  ('c-m-16', null, null, 'medium', 'write', 'permissions', 'Muestra los grupos a los que pertenece tu usuario.', array['groups', 'id', 'id -Gn']::text[], null, null, null, 'Grupos en inglés.', 'groups lista tus grupos. id muestra además tu UID y GID.', null),
  ('c-m-17', null, null, 'medium', 'write', 'permissions', 'Abre una terminal como root usando sudo.', array['sudo -i', 'sudo su', 'sudo su -', 'sudo -s']::text[], null, null, null, 'sudo con la opción de login interactivo.', 'sudo -i inicia una sesión de root. Escribe exit para volver.', null),
  ('c-m-18', null, null, 'medium', 'write', 'search', 'Busca la palabra «error» en /var/log/syslog.', array['grep error /var/log/syslog', 'sudo grep error /var/log/syslog', 'cat /var/log/syslog | grep error']::text[], null, null, null, 'grep palabra archivo.', 'grep error /var/log/syslog muestra las líneas que contienen «error».', null),
  ('c-m-19', null, null, 'medium', 'write', 'search', 'Busca «linux» en notas.txt sin importar mayúsculas o minúsculas.', array['grep -i linux notas.txt']::text[], null, null, null, 'La opción de grep para ignorar mayúsculas es una vocal.', 'grep -i (ignore case) encuentra Linux, LINUX y linux.', '~/Documentos'),
  ('c-m-20', null, null, 'medium', 'write', 'search', 'Busca todos los archivos .txt dentro de tu carpeta personal.', array['find ~ -name "*.txt"', 'find . -name "*.txt"', 'find -name *.txt', 'find -name "*.txt"', 'find ~ -name *.txt', 'find . -name *.txt']::text[], null, null, null, 'find carpeta -name patrón.', 'find ~ -name "*.txt" recorre todas las subcarpetas buscando nombres que terminen en .txt.', null),
  ('c-m-21', null, null, 'medium', 'write', 'search', 'Cuenta cuántos archivos hay en Documentos combinando ls y wc.', array['ls Documentos | wc -l', 'ls ~/Documentos | wc -l']::text[], null, null, null, 'Usa una tubería |.', 'ls genera una línea por archivo y wc -l las cuenta.', null),
