  ('c-d-01', null, null, 'hard', 'write', 'files', 'Comprime la carpeta proyectos en el archivo proyectos.tar.gz.', array['tar -czf proyectos.tar.gz proyectos', 'tar -czvf proyectos.tar.gz proyectos', 'tar czf proyectos.tar.gz proyectos', 'tar czvf proyectos.tar.gz proyectos']::text[], null, null, null, 'tar: c = crear, z = gzip, f = archivo.', 'tar -czf destino.tar.gz carpeta. El nombre del archivo va justo después de f.', null),
