  ('c-d-03', null, null, 'hard', 'write', 'permissions', 'Con notación numérica, deja script.sh así: el dueño lee, escribe y ejecuta; grupo y otros leen y ejecutan.', array['chmod 755 script.sh']::text[], null, null, null, 'rwx = 7, r-x = 5.', '755 = rwxr-xr-x. Es el permiso típico de scripts y programas.', '~/proyectos'),
  ('c-d-04', null, null, 'hard', 'write', 'permissions', 'Cambia de forma recursiva el dueño y el grupo de proyectos/web a www-data.', array['sudo chown -R www-data:www-data proyectos/web', 'sudo chown -R www-data: proyectos/web']::text[], null, null, null, 'chown -R usuario:grupo carpeta.', '-R aplica el cambio a todo lo que hay dentro; usuario:grupo cambia ambos a la vez.', null),
