  ('c-d-08', null, null, 'hard', 'write', 'search', 'Encuentra en /var/log los archivos .log modificados en los últimos 7 días.', array['find /var/log -name "*.log" -mtime -7', 'find /var/log -mtime -7 -name "*.log"', 'find /var/log -name *.log -mtime -7']::text[], null, null, null, 'Combina -name y -mtime.', '-mtime -7 = modificado hace menos de 7 días.', null),
  ('c-d-09', null, null, 'hard', 'write', 'search', 'Cuenta cuántas líneas de /var/log/syslog contienen «error».', array['grep -c error /var/log/syslog', 'grep error /var/log/syslog | wc -l']::text[], null, null, null, 'grep tiene una opción para contar.', 'grep -c devuelve solo el número de coincidencias.', null),
